// Existing completion calls automatically use this richer sound in Story Adventure,
// Word Trails, Trivia, Crosswords and Family Worship. Respect independent SFX settings.
playChime=function(){
 if(!sfxOn||sfxVolume<=0)return;
 let ac;try{ac=audioContext();}catch(_){return;}if(!ac)return;
 const level=Math.pow(Math.max(0,Math.min(100,sfxVolume))/100,.66);
 const now=ac.currentTime+.009;
 // Short rising warm-toned celebratory shimmer rather than a loud arcade alarm.
 [[523.25,0,.52,1],[659.25,.095,.55,.85],[783.99,.19,.62,.8],[1046.5,.295,.77,.58]].forEach(([freq,offset,duration,strength],i)=>{
  try{
   const osc=ac.createOscillator(),gain=ac.createGain();
   osc.type=i===3?'sine':'triangle';
   osc.frequency.setValueAtTime(freq,now+offset);
   const peak=.125*level*strength;
   gain.gain.setValueAtTime(.0001,now+offset);
   gain.gain.exponentialRampToValueAtTime(Math.max(.00011,peak),now+offset+.018);
   gain.gain.exponentialRampToValueAtTime(.0001,now+offset+duration);
   osc.connect(gain);gain.connect(ac.destination);
   osc.start(now+offset);osc.stop(now+offset+duration+.025);
   osc.onended=()=>{try{osc.disconnect();gain.disconnect();}catch(_){}};
  }catch(e){console.warn('Word success sound error',e);}
 });
};
