 if(!panel||!wheel)return;
 const clue=panel.querySelector('.clue'),answer=panel.querySelector('.letter-answer'),note=panel.querySelector('.note'),read=panel.querySelector('.bu3815-read');
 if(!clue||!answer||!note)return;
 const cs=getComputedStyle(panel),gap=parseFloat(cs.rowGap||cs.gap)||3;
 const pad=(parseFloat(cs.paddingTop)||0)+(parseFloat(cs.paddingBottom)||0);
 // Only reserve space for controls currently visible on screen. Hidden legacy
 // answer tracks and Scripture pills must not shrink the wheel.
 const extras=[clue,answer,note,read].filter(Boolean).filter(el=>getComputedStyle(el).display!=='none');
 const reserve=extras.reduce((n,el)=>n+el.getBoundingClientRect().height,0)+pad+gap*(extras.length+1)+6;
 const free=panel.clientHeight-reserve;
