// v3.8.8 — Restore music ducking after the legacy v3.4 audio override.
// No permanent timer: update the volume for ~0.5 seconds only when speech
// begins or ends. This fixes voice/music balance without audio CPU polling.
let bu387DuckGain=1,bu387DuckTimer=null;
const bu387BasePulse=bu25AudioPulse;
bu25AudioPulse=function(){
 bu387BasePulse();
 if(document.hidden||!musicOn){bu387DuckGain=1;if(bu387DuckTimer){clearTimeout(bu387DuckTimer);bu387DuckTimer=null;}return;}
 const target=bu381Voice.active?0.30:1;
 bu387DuckGain+=(target-bu387DuckGain)*0.38;
 if(Math.abs(bu387DuckGain-target)<0.012)bu387DuckGain=target;
 for(const player of Object.values(bu25Audio)){
  if(player&&!player.paused)player.volume=Math.max(0,Math.min(1,player.volume*bu387DuckGain));
 }
 if(bu387DuckGain!==target&&!bu387DuckTimer){
  bu387DuckTimer=setTimeout(()=>{bu387DuckTimer=null;bu25AudioPulse()},45);
 }
};
