const BU3832_QA_PATCHES=[{"id":39,"topic":"cain","oldQ":"How did Cain and Abel earn their living?","changes":{"q":"What work did Cain and Abel do?","explanation":"Genesis 4:2 distinguishes their occupations: Abel became a shepherd, while Cain cultivated the ground."},"group":null},{"id":55,"topic":"cain","oldQ":"Where did Cain settle after leaving Jehovah’s presence?","changes":{"q":"Where did Cain go to live after leaving Jehovah’s presence?","choices":["The land of Exile (Nod)","The city of Jericho","The mountains of Ararat","The land of Goshen"],"explanation":"Genesis 4:16 calls the place the land of Exile; the name Nod appears in the translation footnote."},"group":null},{"id":64,"topic":"noah","oldQ":"What did a returning dove carry?","changes":{"q":"What did Noah see when he removed the covering of the ark?","choices":["The surface of the ground was drying","The waters had turned red","A great city near the ark","A rainbow already filling the sky"],"ref":"Genesis 8:13","explanation":"After removing the covering of the ark, Noah saw that the surface of the ground was drying."},"group":null},{"id":95,"topic":"babel","oldQ":"How many languages did the people speak before they began their building project?","changes":{},"group":"babel-one-language"},{"id":96,"topic":"babel","oldQ":"What material did the builders use instead of stone?","changes":{},"group":"babel-brick-material"},{"id":97,"topic":"babel","oldQ":"Why did the people want a great tower and city?","changes":{},"group":"babel-tower-purpose"},{"id":98,"topic":"babel","oldQ":"What made it impossible for the people to keep working together as before?","changes":{},"group":"babel-language-confusion"},{"id":102,"topic":"babel","oldQ":"What did the people say they wanted to make for themselves?","changes":{},"group":"babel-tower-purpose"},{"id":105,"topic":"babel","oldQ":"What was the main construction technique mentioned in Genesis 11:3?","changes":{},"group":"babel-brick-material"},{"id":107,"topic":"babel","oldQ":"Why did the people no longer understand one another?","changes":{},"group":"babel-language-confusion"},{"id":110,"topic":"babel","oldQ":"What was the language situation across the earth at the start of Genesis 11?","changes":{},"group":"babel-one-language"},{"id":111,"topic":"babel","oldQ":"How did the people plan to prevent being scattered?","changes":{},"group":"babel-tower-purpose"},{"id":114,"topic":"abraham","oldQ":"What moved Abram to leave his previous home and journey toward a new land?","changes":{"ref":"Genesis 12:1–4; Hebrews 11:8","explanation":"Hebrews 11:8 explicitly says that Abraham obeyed by faith when called to leave; Genesis 12:1–4 records Jehovah’s direction and promise."},"group":null},{"id":124,"topic":"abraham","oldQ":"What did Abram say about Lot in Genesis 13 before they separated?","changes":{"q":"Why did Abram ask Lot to avoid quarreling?","choices":["They were close relatives","Lot had become ruler of Ur","They had no livestock to care for","They were leaving Egypt forever"],"ref":"Genesis 13:7–9","explanation":"Their herders had quarreled, and Abram appealed for peace because he and Lot belonged to the same family. They were uncle and nephew."},"group":null},{"id":150,"topic":"joshua","oldQ":"What did the Jordan’s waters do when the priests carrying the Ark stepped in?","changes":{"choices":["The upstream waters stood still while downstream water drained","The waters froze into ice","The river became bitter","The river turned red"],"explanation":"Joshua 3:13–17 describes the upstream waters standing still while the downstream waters drained away, allowing Israel to cross."},"group":null},{"id":179,"topic":"ruth","oldQ":"Which woman stayed with Naomi and returned to Judah?","changes":{},"group":"ruth-choice-stay"},{"id":190,"topic":"ruth","oldQ":"Who expressed a desire to share Naomi’s people and God?","changes":{"q":"What did Ruth say about where she would be buried?","choices":["Where Naomi died, she would die and be buried","Beside the king’s palace","In the land of Moab regardless of Naomi","In the fields where she gleaned"],"ref":"Ruth 1:17","explanation":"Ruth’s promise included staying with Naomi not only in life but also in death; she said she would be buried where Naomi was."},"group":null},{"id":194,"topic":"ruth","oldQ":"What did Ruth tell Naomi about where she would go?","changes":{},"group":"ruth-choice-stay"},{"id":210,"topic":"david","oldQ":"What did David refuse to rely on when approaching Goliath?","changes":{},"group":"david-sauls-armor"},{"id":212,"topic":"david","oldQ":"Why did David take off Saul's armor before approaching Goliath?","changes":{},"group":"david-sauls-armor"},{"id":216,"topic":"david","oldQ":"What did David say the battle belonged to?","changes":{},"group":"david-battle-belongs"},{"id":217,"topic":"david","oldQ":"Who said the battle belonged to Jehovah?","changes":{},"group":"david-battle-belongs"},{"id":222,"topic":"david","oldQ":"What contrast troubled David when he spoke to Nathan in 2 Samuel 7?","changes":{"q":"What contrast did David point out to Nathan in 2 Samuel 7?","explanation":"David pointed out that he was living in a cedar house while the Ark of Jehovah remained under tent cloth. The passage does not expressly name his emotion."},"group":null},{"id":239,"topic":"solomon","oldQ":"How did Jehovah communicate with Solomon at Gibeon?","changes":{},"group":"solomon-dream"},{"id":242,"topic":"solomon","oldQ":"What revealed the true mother's identity?","changes":{"choices":["Her concern that the child remain alive","Her insistence that the king punish the other woman","Her knowledge of the palace guards","Her request that both women leave Jerusalem"],"explanation":"The true mother asked that the child be spared, while the other woman accepted the proposed division. Solomon recognized the mother’s compassion."},"group":null},{"id":251,"topic":"solomon","oldQ":"What did Jehovah offer Solomon in a dream?","changes":{},"group":"solomon-dream"},{"id":281,"topic":"elijah","oldQ":"What food did an angel provide Elijah in the wilderness?","changes":{"choices":["A round loaf on heated stones and a jug of water","Fish and loaves","Manna in a golden jar","Fruit from Eden"],"explanation":"The account describes a round loaf on heated stones and a jug of water beside Elijah, who needed strength for the journey."},"group":null},{"id":290,"topic":"elisha","oldQ":"How did Naaman initially react to Elisha's instruction?","changes":{"choices":["He became angry","He immediately obeyed and was healed","He asked Elisha to take him to Jericho","He offered to become king of Israel"],"explanation":"Naaman became indignant because he expected the prophet to come out and act differently; later his servants persuaded him to obey."},"group":null},{"id":294,"topic":"elisha","oldQ":"What happened to Gehazi after his deception was exposed?","changes":{"choices":["He was afflicted with leprosy","He was crowned king of Israel","He was appointed chief priest","He was rewarded with more silver"],"explanation":"After Gehazi admitted where he had been, Elisha said Naaman’s leprosy would cling to him, and he left leprous."},"group":null},{"id":295,"topic":"elisha","oldQ":"Whose mantle fell to Elisha after Elijah was taken away?","changes":{"q":"What did Elisha ask Elijah for before Elijah was taken away?","choices":["A double portion of his spirit","A royal throne","A new suit of armor","A house in Jerusalem"],"ref":"2 Kings 2:9–10","explanation":"Elisha asked for a double portion of Elijah’s spirit. Elijah said that whether the request was granted would depend on what Elisha saw."},"group":null},{"id":296,"topic":"elisha","oldQ":"What did Elisha use to strike the Jordan and divide its water?","changes":{"choices":["Elijah’s official garment","A bronze sword","A wooden rod made by Moses","A silver staff"],"explanation":"Elisha used the official garment of Elijah that had fallen off him; the Jordan’s waters divided when he struck them."},"group":null},{"id":307,"topic":"esther","oldQ":"Who became queen and helped save her people?","changes":{"q":"Which queen decided to approach the king to plead for her people?","ref":"Esther 2:17; 4:15–17","explanation":"Esther called for fasting and resolved to approach the king despite the danger, in an effort to help her people."},"group":null},{"id":311,"topic":"esther","oldQ":"What did Esther ask the Jews in Shushan to do before she approached the king?","changes":{},"group":"esther-fast"},{"id":314,"topic":"esther","oldQ":"What was Haman's reaction to Mordecai's refusal to bow?","changes":{},"group":"esther-haman-anger"},{"id":324,"topic":"esther","oldQ":"Why did Haman become enraged at Mordecai?","changes":{},"group":"esther-haman-anger"},{"id":325,"topic":"esther","oldQ":"For how many days did Esther request fasting before she approached the king?","changes":{},"group":"esther-fast"},{"id":330,"topic":"esther","oldQ":"What did the king order done to honor Mordecai?","changes":{"q":"When the king asked how to honor someone, whom did Haman assume the king meant?","choices":["Haman himself","Mordecai","Esther","The king’s doorkeepers"],"ref":"Esther 6:6","explanation":"Haman assumed he was the one the king wished to honor, not realizing that Mordecai was the intended recipient."},"group":null},{"id":332,"topic":"daniel","oldQ":"How often did Daniel pray each day despite the decree?","changes":{},"group":"daniel-prayer"},{"id":340,"topic":"daniel","oldQ":"What did Daniel refuse to give up?","changes":{},"group":"daniel-prayer"},{"id":341,"topic":"daniel","oldQ":"Which detail shows Daniel did not change his worship routine after the decree?","changes":{},"group":"daniel-prayer"},{"id":344,"topic":"daniel","oldQ":"Who interpreted Nebuchadnezzar’s dream of a great image?","changes":{"ref":"Daniel 2:27–28, 36–45","explanation":"Daniel said the God in heaven reveals secrets, and then explained the meaning of the image in Nebuchadnezzar’s dream."},"group":null},{"id":362,"topic":"jesusbirth","oldQ":"Which prophet was cited concerning the birth in Bethlehem?","changes":{"ref":"Micah 5:2; Matthew 2:5–6","explanation":"Micah 5:2 foretells a ruler coming from Bethlehem; Matthew 2:5–6 recounts that prophecy being cited."},"group":null},{"id":396,"topic":"parables","oldQ":"What did the small mustard grain become in Jesus’ illustration?","changes":{"choices":["A tree in which birds could find shelter","A stone pillar","A ship","A river"],"explanation":"In the illustration, a tiny mustard seed grows into a tree, and birds find shelter among its branches."},"group":null},{"id":412,"topic":"miracles","oldQ":"What illness did Jesus heal in the man lowered through the roof?","changes":{"q":"What condition did Jesus heal in the man lowered through the roof?","explanation":"The man was paralyzed. Friends lowered him through an opening in the roof, and Jesus told him to get up and walk."},"group":null},{"id":434,"topic":"acts","oldQ":"What type of officer was Cornelius?","changes":{"q":"What military role did Cornelius hold?","explanation":"Acts 10:1 identifies Cornelius as an army officer of the Italian unit based in Caesarea."},"group":null},{"id":450,"topic":"acts","oldQ":"Where did Philip baptize the Ethiopian man?","changes":{"q":"Where does Acts 8 say Philip baptized the Ethiopian official?","choices":["In a body of water along their journey","Inside Jerusalem’s temple","At the Sea of Galilee","In the house of Cornelius"],"explanation":"The account describes the travelers coming to water and going down into it; it does not specify a named geographic location."},"group":null},{"id":458,"topic":"paul","oldQ":"Who accompanied Paul after he selected a young disciple at Lystra?","changes":{"q":"Which young disciple from Lystra did Paul invite to accompany him?","explanation":"Acts 16:1–3 specifically names Timothy, the disciple at Lystra whom Paul wanted to accompany him. Silas was already traveling with Paul."},"group":null},{"id":474,"topic":"paul","oldQ":"To which Roman emperor did Paul appeal while on trial?","changes":{"q":"To whom did Paul appeal to have his case heard?","choices":["Caesar","Governor Felix","King Nebuchadnezzar","King Cyrus"],"explanation":"Paul appealed to Caesar while before Festus. Caesar is an imperial title, not the personal name supplied in this passage."},"group":null},{"id":478,"topic":"samuel","oldQ":"Who was the priest Samuel first thought had called him?","changes":{},"group":"samuel-eli-recognition"},{"id":480,"topic":"samuel","oldQ":"What was Samuel instructed to say when called again?","changes":{"q":"What did Eli instruct Samuel to say if Jehovah called him again?","choices":["Speak, Jehovah, for your servant is listening","Speak, and your servant will obey","Tell me who has called me","I am ready to go"],"ref":"1 Samuel 3:9","explanation":"Eli instructed Samuel to address Jehovah by name; in verse 10 Samuel’s later response is slightly shorter."},"group":null},{"id":483,"topic":"samuel","oldQ":"Who helped Samuel understand who was calling him?","changes":{},"group":"samuel-eli-recognition"},{"id":485,"topic":"samuel","oldQ":"What time of day was it when Samuel first heard the call?","changes":{"q":"According to 1 Samuel 3:3, what had not yet been extinguished when Samuel lay down?","choices":["The lamp of God","A torch outside the palace","A fire on Mount Carmel","A lamp in Pharaoh’s house"],"ref":"1 Samuel 3:3","explanation":"The lamp of God had not yet been extinguished when Samuel lay down near the Ark in the tabernacle."},"group":null},{"id":496,"topic":"samuel","oldQ":"Who did Samuel later anoint at Bethlehem?","changes":{},"group":"samuel-king-david"},{"id":497,"topic":"samuel","oldQ":"Which of Jesse’s sons was eventually chosen?","changes":{},"group":"samuel-king-david"},{"id":505,"topic":"jonah","oldQ":"What did the people of Nineveh announce after Jonah's warning?","changes":{"choices":["A fast","A procession of priests in the temple","A festival of new crops","A royal pilgrimage"],"explanation":"After Jonah’s warning, the people of Nineveh declared a fast and put on sackcloth, showing their response to his message."},"group":null},{"id":509,"topic":"jonah","oldQ":"Why did Jonah say he had tried to flee in the first place?","changes":{},"group":"jonah-reason-for-fleeing"},{"id":523,"topic":"jonah","oldQ":"What did Jonah say he knew about Jehovah that made him reluctant?","changes":{},"group":"jonah-reason-for-fleeing"},{"id":527,"topic":"nehemiah","oldQ":"How did the workers respond to threats of attack?","changes":{},"group":"nehemiah-pray-guards"},{"id":528,"topic":"nehemiah","oldQ":"What did some load carriers do while working?","changes":{},"group":"nehemiah-build-weapons"},{"id":532,"topic":"nehemiah","oldQ":"Which response best shows how Nehemiah combined faith with action?","changes":{},"group":"nehemiah-pray-guards"},{"id":533,"topic":"nehemiah","oldQ":"What did guards carry to help protect the workers?","changes":{},"group":"nehemiah-build-weapons"},{"id":541,"topic":"nehemiah","oldQ":"Which families joined the priests and workers to repair different sections?","changes":{"q":"Which high priest and his brothers built the Sheep Gate?","choices":["Eliashib and the priests","Elisha and the prophets","Mordecai and the gatekeepers","Daniel and his companions"],"ref":"Nehemiah 3:1","explanation":"Eliashib the high priest and his fellow priests worked on the Sheep Gate; chapter 3 lists many other groups repairing different sections."},"group":null},{"id":542,"topic":"nehemiah","oldQ":"What did Nehemiah urge wealthy Jews to stop doing to needy brothers?","changes":{"q":"What did Nehemiah urge wealthy Jews to stop taking from their needy brothers?","choices":["Interest and pledged fields","Temple offerings","Stones for wall repairs","Food for the priests"],"explanation":"Nehemiah challenged the demand for interest and told the lenders to restore the fields, vineyards, olive groves, and houses they had taken."},"group":null},{"id":550,"topic":"psalms","oldQ":"What does Psalm 37:8 tell the reader to abandon?","changes":{},"group":"psalms-37-promise"},{"id":551,"topic":"psalms","oldQ":"Who will no longer be found according to Psalm 37:10?","changes":{"choices":["The wicked","The righteous","Those practicing peace","The mild-tempered"],"explanation":"Psalm 37:10 contrasts the coming absence of the wicked with the prospect for the meek in the following verse."},"group":null},{"id":554,"topic":"psalms","oldQ":"What will the righteous possess, according to Psalm 37:29?","changes":{},"group":"earth-promise"},{"id":555,"topic":"psalms","oldQ":"Which attitude does Psalm 37:7 encourage when others prosper by schemes?","changes":{},"group":"psalm37-wait-patiently"},{"id":559,"topic":"psalms","oldQ":"What does Psalm 37:8 urge readers to abandon?","changes":{},"group":"psalms-37-promise"},{"id":561,"topic":"psalms","oldQ":"What does Psalm 37:7 encourage the reader to do when wrongdoers seem successful?","changes":{},"group":"psalm37-wait-patiently"},{"id":575,"topic":"psalms","oldQ":"What does Psalm 83:18 say about the name Jehovah?","changes":{},"group":"psalms-jehovah-name"},{"id":580,"topic":"proverbs","oldQ":"What will Jehovah do for the paths of a person who acknowledges him?","changes":{"choices":["Make them straight","Turn them into rivers","Remove every need to make decisions","Make them lead back to Egypt"],"explanation":"Proverbs 3:5–6 encourages trust in Jehovah rather than relying solely on our own understanding; acknowledging him is linked to straight paths."},"group":null},{"id":596,"topic":"proverbs","oldQ":"According to Proverbs 27:17, how can one person help another?","changes":{"q":"What comparison does Proverbs 27:17 use to describe how one person helps another?","explanation":"The proverb compares one person sharpening another to iron sharpening iron, emphasizing the value of constructive interaction."},"group":null},{"id":609,"topic":"sermon","oldQ":"Where did Jesus teach about being reconciled with a brother before offering a gift?","changes":{"q":"In Jesus’ illustration, where should a worshipper leave a gift before making peace with a brother?","choices":["In front of the altar","At the city gate","Beside the sea","In a royal palace"],"explanation":"Jesus said to leave the gift in front of the altar and first make peace with the brother; he was using an illustration, not saying the teaching itself took place at an altar."},"group":null},{"id":610,"topic":"sermon","oldQ":"What did Jesus say a person should do with a right eye that causes stumbling, figuratively?","changes":{"q":"In Jesus’ figurative illustration, what should a person do with an eye that causes stumbling?","explanation":"Jesus used a forceful illustration about removing what causes stumbling, not a command to harm one’s body."},"group":null},{"id":715,"topic":"promise","oldQ":"What will be no more according to Revelation 21:4?","changes":{},"group":"promise-no-death"},{"id":721,"topic":"promise","oldQ":"What expression describes God's future closeness to people?","changes":{"q":"What does Revelation 21:6 offer freely to anyone who is thirsty?","choices":["Water from the spring of the water of life","A royal crown made of iron","A house built of cedar","A chariot of fire"],"ref":"Revelation 21:6","explanation":"The speaker promises water from the spring of the water of life without charge, as part of the vision of all things being made new."},"group":null},{"id":724,"topic":"promise","oldQ":"What kind of world does Revelation 21:1 speak of?","changes":{"q":"How many gates did John see in the wall of New Jerusalem?","choices":["Twelve","Four","Seven","Twenty-four"],"ref":"Revelation 21:12–13","explanation":"John describes 12 gates, with three facing each of the four directions."},"group":null},{"id":730,"topic":"promise","oldQ":"What does Psalm 37:29 say about the righteous?","changes":{},"group":"earth-promise"},{"id":737,"topic":"promise","oldQ":"What does Revelation 21:4 identify as the former things?","changes":{},"group":"promise-no-death"},{"id":740,"topic":"jehovah","oldQ":"According to Micah 6:8, what does Jehovah ask a person to practice?","changes":{"explanation":"Micah 6:8 urges a person to exercise justice, cherish loyalty, and walk in modesty with God."},"group":null},{"id":743,"topic":"jehovah","oldQ":"How does Exodus 34:6–7 describe Jehovah’s mercy alongside his justice?","changes":{"explanation":"Exodus 34:6–7 describes Jehovah as merciful and forgiving while also taking guilt seriously; mercy and justice are presented together."},"group":null},{"id":748,"topic":"jehovah","oldQ":"What personal name does Psalm 83:18 identify as belonging to the Most High?","changes":{},"group":"psalms-jehovah-name"},{"id":757,"topic":"jehovah","oldQ":"According to Acts 17:24, what does God not live in?","changes":{"q":"Which statement about God did Paul make in Acts 17:24?","choices":["He does not live in handmade temples","He depends on humans to build his dwelling","He created only the seas","He needs human service to stay alive"],"ref":"Acts 17:24–25","explanation":"Paul reasoned that the Creator does not dwell in temples made with hands and does not depend on human service for life."},"group":null},{"id":781,"topic":"jesusministry","oldQ":"What did Jesus say about his message in Luke 4:43?","changes":{},"group":"kingdom-preach-purpose"},{"id":790,"topic":"kingdom","oldQ":"Which quality is praised between the gathering for Armageddon and the seventh bowl?","changes":{"q":"According to Revelation 16:15, who is called happy?","choices":["The one who stays awake and keeps his outer garments","The one who knows the battle’s exact date","The one who gathers many weapons","The one who travels to a certain mountain"],"ref":"Revelation 16:15","explanation":"The verse pronounces happy the one who stays awake and keeps his outer garments; it does not reveal an exact date."},"group":null},{"id":798,"topic":"kingdom","oldQ":"What did Jesus say was a reason he had been sent?","changes":{},"group":"kingdom-preach-purpose"},{"id":802,"topic":"kingdom","oldQ":"According to Daniel 7:14, to whom was dominion given?","changes":{},"group":"kingdom-son-of-man"},{"id":806,"topic":"prophecy","oldQ":"Who approached the Ancient of Days in Daniel 7:13?","changes":{},"group":"kingdom-son-of-man"},{"id":817,"topic":"prophecy","oldQ":"Which prophet spoke of God pouring out his spirit on all sorts of flesh?","changes":{},"group":"prophecy-spirit-outpouring"},{"id":821,"topic":"prophecy","oldQ":"What was to be poured out on sons and daughters in Joel’s prophecy?","changes":{},"group":"prophecy-spirit-outpouring"},{"id":822,"topic":"prophecy","oldQ":"What did Daniel see coming with the clouds of the heavens?","changes":{},"group":"kingdom-son-of-man"},{"id":823,"topic":"prophecy","oldQ":"What happens to war between nations in Isaiah’s prophecy?","changes":{"q":"According to Isaiah 2:4, what will swords be beaten into?","choices":["Plowshares","Royal crowns","Prison chains","Bronze shields"],"ref":"Isaiah 2:4","explanation":"Isaiah describes tools of war being turned into farming implements—swords into plowshares and spears into pruning shears."},"group":null},{"id":832,"topic":"job","oldQ":"Who was reproved for not speaking correctly about Jehovah as Job had?","changes":{},"group":"job-three-companions"},{"id":833,"topic":"job","oldQ":"In Job 42:5–6, how did Job describe the change in his understanding?","changes":{"explanation":"Job contrasted what he had previously heard about Jehovah with now speaking of seeing him. The language expresses a change in his understanding, not necessarily literal eyesight."},"group":null},{"id":843,"topic":"job","oldQ":"What were the names of Job’s three companions who came to console him?","changes":{},"group":"job-three-companions"},{"id":846,"topic":"job","oldQ":"What animals did Jehovah use among his questions to Job?","changes":{"explanation":"Jehovah drew Job’s attention to Behemoth in chapter 40 and Leviathan in chapter 41. Both passages belong to the same series of questions."},"group":null},{"id":855,"topic":"christianliving","oldQ":"What effect does perfect love have on fear according to 1 John 4:18?","changes":{"q":"According to 1 John 4:18, what does perfect love do to fear associated with punishment?","explanation":"The verse explains that fear connected with punishment restrains love; it does not teach that every form of respectful fear is wrong."},"group":null}];
const BU3832_HISTORY_ALIASES=Object.create(null);
for (const patch of BU3832_QA_PATCHES){
 const matches=(BU34_BANK[patch.topic]||[]).filter(q=>q.q===patch.oldQ);
 if(matches.length!==1)throw new Error('Bible content QA patch mismatch: '+patch.id+' '+patch.oldQ);
 const question=matches[0],oldId=bu3829QuestionIdentity(question);
 Object.assign(question,patch.changes);
 if(patch.changes.choices)question.correct=0;
 if(patch.group)question.__qaGroup='scripture-fact/'+patch.group;
 const canonical=question.__qaGroup||bu3829QuestionIdentity(question);
 if(oldId!==canonical)BU3832_HISTORY_ALIASES[oldId]=canonical;
}

/* Round 13 individualized explanation review; authored from recorded NWT chapter comparisons. */
const BU3832_R13_EXPLANATIONS=[{"id":465,"topic":"paul","q":"Where was Saul born according to his later testimony?","explanation":"In his defense before the crowd, Paul identified his birthplace as Tarsus in Cilicia, while explaining that he was educated in Jerusalem."},{"id":466,"topic":"paul","q":"At whose feet did Saul receive instruction in Jerusalem?","explanation":"Paul said he was educated at the feet of Gamaliel, distinguishing his training in Jerusalem from his birthplace in Tarsus."},{"id":467,"topic":"paul","q":"Who accompanied Barnabas and Saul on their first missionary journey?","explanation":"Acts 13:4–5 says that John accompanied Barnabas and Saul as their attendant when they traveled to Cyprus."},{"id":468,"topic":"paul","q":"Who listened carefully to Paul’s message in Berea and examined the Scriptures daily?","explanation":"The Jews in Beroea received the message eagerly and carefully examined the Scriptures daily to see whether the things taught were so."},{"id":469,"topic":"paul","q":"Where did Paul speak about an altar inscribed to an unknown god?","explanation":"In Athens, Paul referred to an altar dedicated to an unknown god as he began speaking about the Creator."},{"id":470,"topic":"paul","q":"At what prominent place in Athens did Paul address listeners?","explanation":"The Athenians took Paul to the Areopagus, where they asked him to explain the new teaching he was presenting."},{"id":471,"topic":"paul","q":"Who worked as a tentmaker along with Paul in Corinth?","explanation":"Aquila and his wife Priscilla shared Paul's trade of tentmaking, so Paul stayed and worked with them in Corinth."},{"id":472,"topic":"paul","q":"What happened to Eutychus during Paul’s long talk?","explanation":"Eutychus fell asleep during Paul's lengthy talk and fell from a third-story window; Paul went down to him and the account says he was alive."},{"id":473,"topic":"paul","q":"Who warned Paul by using his belt as a prophetic sign?","explanation":"Agabus used Paul's belt to illustrate the bonds awaiting the belt's owner in Jerusalem."},{"id":475,"topic":"paul","q":"What disaster struck the ship carrying Paul toward Rome?","explanation":"The voyage toward Rome faced violent weather, and Acts 27 describes the ship being lost while those aboard reached land safely."},{"id":476,"topic":"paul","q":"How did Paul describe his responsibility to finish his ministry?","explanation":"Paul said he did not regard his life as dear to himself if he could finish his course and complete the ministry received from the Lord Jesus."},{"id":565,"topic":"psalms","q":"According to Psalm 1, what is the person who delights in Jehovah’s law compared to?","explanation":"Psalm 1 compares the one who delights in Jehovah's law to a tree planted by streams of water, bearing fruit in its season."},{"id":566,"topic":"psalms","q":"How frequently does Psalm 1 describe that person reading God’s law?","explanation":"The psalmist describes reading God's law in an undertone day and night, making it a regular focus rather than an occasional activity."},{"id":567,"topic":"psalms","q":"According to Psalm 8:3-4, what makes the psalmist wonder about God’s care for humans?","explanation":"Looking at the moon, stars, and heavens moves the psalmist to ask why God takes notice of mortal humans."},{"id":568,"topic":"psalms","q":"What is Jehovah compared to in Psalm 18:2?","explanation":"David describes Jehovah as his rock, fortress, and rescuer, expressing a sense of protection and security."},{"id":569,"topic":"psalms","q":"How do the heavens give testimony according to Psalm 19:1?","explanation":"Psalm 19 depicts the heavens as declaring God's glory, with the expanse announcing the work of his hands."},{"id":570,"topic":"psalms","q":"In Psalm 23, through what frightening setting does the shepherd guide the writer?","explanation":"Psalm 23 describes a valley of deep shadow, yet the shepherd's presence and guidance reassure the psalmist."},{"id":571,"topic":"psalms","q":"What does Psalm 27:1 call Jehovah?","explanation":"The psalmist calls Jehovah his light and salvation, then asks whom he should fear."},{"id":572,"topic":"psalms","q":"What does Psalm 34:8 invite people to do concerning Jehovah?","explanation":"The invitation to taste and see is an encouragement to experience and recognize Jehovah's goodness, not a literal instruction about food."},{"id":573,"topic":"psalms","q":"According to Psalm 46:9, what does Jehovah bring to an end?","explanation":"Psalm 46 describes Jehovah bringing wars to an end throughout the earth, breaking the bow and shattering the spear."},{"id":574,"topic":"psalms","q":"What does Psalm 55:22 encourage readers to throw on Jehovah?","explanation":"The verse invites a person to throw his burden on Jehovah and says that he will sustain the righteous one."},{"id":575,"topic":"psalms","q":"What does Psalm 83:18 say about the name Jehovah?","explanation":"Psalm 83:18 identifies Jehovah by name as the Most High over all the earth; it is not merely describing a title given to a human ruler."},{"id":576,"topic":"psalms","q":"According to Psalm 119:105, what is God’s word like for the writer?","explanation":"The writer compares God's word to a lamp for his foot and a light for his path, showing its value for guidance."},{"id":631,"topic":"prayer","q":"What did Jesus say about repeating the same words over and over in prayer?","explanation":"Jesus warned against empty repetition in prayer; his point was that many words do not make a prayer more likely to be heard."},{"id":632,"topic":"prayer","q":"Where did Jesus suggest praying rather than seeking attention?","explanation":"Jesus contrasted private prayer with praying publicly for attention, emphasizing sincerity rather than an audience."},{"id":633,"topic":"prayer","q":"What did Jesus say the Father already knows before we ask?","explanation":"Jesus said the Father knows what his worshippers need even before they ask him, so prayer is not about supplying God with missing information."},{"id":634,"topic":"prayer","q":"For whose will did Jesus teach his followers to pray?","explanation":"In the model prayer, Jesus taught his followers to ask that God's will take place on earth as it does in heaven."},{"id":635,"topic":"prayer","q":"What should a person do toward others when asking for forgiveness?","explanation":"After teaching a prayer for forgiveness, Jesus emphasized forgiving people who trespass against us."},{"id":636,"topic":"prayer","q":"What was Jesus doing when the disciples asked him to teach them to pray?","explanation":"Luke first describes Jesus praying in a certain place; after he finished, a disciple asked him to teach them to pray."},{"id":637,"topic":"prayer","q":"What example did Jesus use to illustrate persistence in asking?","explanation":"Jesus pictured a friend coming at midnight to ask for three loaves of bread, illustrating persistence in asking."},{"id":638,"topic":"prayer","q":"Which three actions did Jesus encourage in Luke 11:9?","explanation":"Jesus encouraged his listeners to keep asking, seeking, and knocking, underscoring perseverance in prayer."},{"id":639,"topic":"prayer","q":"What did Jesus say the Father gives to those asking him?","explanation":"Jesus said that the Father in heaven will give holy spirit to those asking him, comparing his generosity with that of human fathers."},{"id":640,"topic":"prayer","q":"Where did Jesus go to pray on the night before his death?","explanation":"Luke says Jesus went to the Mount of Olives, as was his custom, and there prayed before his arrest."},{"id":641,"topic":"prayer","q":"What did Jesus request about his Father’s will during that prayer?","explanation":"Jesus expressed his own wish but submitted to his Father, asking that the Father's will take place rather than his own."},{"id":642,"topic":"prayer","q":"According to 1 John 5:14, what gives confidence that God hears requests?","explanation":"John links confidence in prayer to making requests according to God's will, rather than assuming every request must be granted."},{"id":726,"topic":"promise","q":"What does Isaiah 65:17 promise Jehovah will create?","explanation":"Isaiah says Jehovah will create new heavens and a new earth, with the former things no longer being called to mind."},{"id":727,"topic":"promise","q":"What does Isaiah 65:21 say people will build and enjoy?","explanation":"The prophecy describes people building houses and actually occupying them, in contrast with another person taking what they built."},{"id":728,"topic":"promise","q":"According to Isaiah 65:22, who will enjoy what they plant?","explanation":"Isaiah says that those who plant vineyards will eat their fruit, describing the enjoyment of one's own work."},{"id":729,"topic":"promise","q":"What will the wolf and lamb do in Isaiah 65:25?","explanation":"Isaiah describes the wolf and lamb feeding together, an image within the prophecy's peaceful setting."},{"id":730,"topic":"promise","q":"What does Psalm 37:29 say about the righteous?","explanation":"Psalm 37:29 connects righteousness with possessing the earth and living forever on it."},{"id":731,"topic":"promise","q":"What happens to deserts and parched places in Isaiah 35:1?","explanation":"Isaiah pictures wilderness and parched land becoming glad and the desert blossoming, expressing a dramatic change for the better."},{"id":732,"topic":"promise","q":"What does Isaiah 35:5 promise will happen to the blind?","explanation":"Isaiah 35:5 describes the eyes of the blind being opened along with the ears of the deaf being unstopped."},{"id":733,"topic":"promise","q":"What ability is restored to the lame person in Isaiah 35:6?","explanation":"The prophecy describes the lame person leaping like a deer, using vivid language for restored ability."},{"id":734,"topic":"promise","q":"What does Isaiah 33:24 say no resident will say?","explanation":"Isaiah 33:24 promises that no resident will say 'I am sick' and also speaks of forgiveness for the people dwelling there."},{"id":735,"topic":"promise","q":"What does John 5:28-29 describe for those in the memorial tombs?","explanation":"Jesus said those in the memorial tombs will hear his voice and come out; the verses also distinguish outcomes according to conduct."},{"id":736,"topic":"promise","q":"According to Revelation 22:2, what are the leaves of the trees for?","explanation":"Revelation describes the leaves of the trees as being for the healing of the nations, in a vision of the river of water of life."},{"id":737,"topic":"promise","q":"What does Revelation 21:4 identify as the former things?","explanation":"Revelation 21:4 says death will be no more and that mourning, outcry, and pain will be gone; it calls these the former things."},{"id":748,"topic":"jehovah","q":"What personal name does Psalm 83:18 identify as belonging to the Most High?","explanation":"Psalm 83:18 supplies the divine name Jehovah and describes him as the Most High over all the earth."},{"id":749,"topic":"jehovah","q":"How does Deuteronomy 32:4 describe Jehovah’s activity?","explanation":"Deuteronomy calls Jehovah the Rock and says his work is perfect, all his ways are justice, and he is never unjust."},{"id":750,"topic":"jehovah","q":"What does James 1:17 say is true about God’s gifts?","explanation":"James attributes every good gift and every perfect present to the Father of the celestial lights, who does not change."},{"id":751,"topic":"jehovah","q":"What does Psalm 86:5 say Jehovah is ready to do?","explanation":"The psalmist describes Jehovah as good and ready to forgive, abundant in loyal love toward those who call on him."},{"id":752,"topic":"jehovah","q":"What does Isaiah 40:26 encourage people to lift their eyes to observe?","explanation":"Isaiah invites people to lift their eyes to the heavens and consider the One who brings out the army of stars by number."},{"id":753,"topic":"jehovah","q":"According to Isaiah 40:28, what does Jehovah never experience?","explanation":"Isaiah says Jehovah, the Creator of the ends of the earth, never tires or grows weary, and his understanding is beyond searching out."},{"id":754,"topic":"jehovah","q":"What does Psalm 34:18 say Jehovah is close to?","explanation":"Psalm 34 says Jehovah is near to the brokenhearted and saves those crushed in spirit."},{"id":755,"topic":"jehovah","q":"What does 1 Peter 5:7 encourage believers to throw on Jehovah?","explanation":"Peter encourages believers to throw all their anxiety on God and gives the reason: he cares for them."},{"id":756,"topic":"jehovah","q":"What did Jesus call Jehovah in John 17:3?","explanation":"Jesus addressed his Father as the only true God and distinguished him from Jesus Christ, whom the Father sent."},{"id":758,"topic":"jehovah","q":"What does Psalm 145:9 say about Jehovah’s goodness?","explanation":"The psalmist says Jehovah is good to all and that his mercy is evident in all his works."},{"id":759,"topic":"jehovah","q":"What did Jehovah tell Moses about his own name?","explanation":"Jehovah instructed Moses to tell the Israelites that Jehovah, the God of their forefathers, had sent him; he identified this as his name forever."},{"id":858,"topic":"christianliving","q":"What does Galatians 5:22-23 call love, joy, and peace?","explanation":"Paul names love, joy, peace, and other qualities as the fruitage of the spirit, then says there is no law against such things."},{"id":860,"topic":"christianliving","q":"What does Ephesians 4:26 caution people against when angry?","explanation":"Paul acknowledges that anger can arise but warns against continuing in a provoked state as the day ends."},{"id":861,"topic":"christianliving","q":"According to Ephesians 4:29, what sort of speech should come from our mouths?","explanation":"Paul directs Christians to avoid rotten speech and instead speak what builds others up according to the need."},{"id":862,"topic":"christianliving","q":"What does Colossians 3:13 encourage when someone has a cause for complaint?","explanation":"Colossians urges people to continue putting up with one another and forgiving freely, following the forgiveness they themselves received."},{"id":863,"topic":"christianliving","q":"What quality does Colossians 3:14 describe as a perfect bond of union?","explanation":"Colossians places love above the other qualities and calls it a perfect bond of union."},{"id":864,"topic":"christianliving","q":"What does Romans 12:18 say Christians should pursue as far as it depends on them?","explanation":"Romans says to be peaceable with all people, if possible and as far as it depends on us; it recognizes that peace is not always entirely in one person's control."},{"id":865,"topic":"christianliving","q":"How does Romans 12:21 say evil should be conquered?","explanation":"Rather than being conquered by evil, Romans instructs Christians to keep conquering evil with good."},{"id":866,"topic":"christianliving","q":"What does Philippians 4:6 encourage instead of being anxious?","explanation":"Paul urges prayer and supplication with thanksgiving in every matter and connects this counsel with freedom from anxiety."},{"id":867,"topic":"christianliving","q":"What should believers keep doing according to Hebrews 10:24-25?","explanation":"Hebrews encourages consideration for one another to motivate love and fine works, and says not to neglect gathering together."},{"id":868,"topic":"christianliving","q":"What does James 3:17 list as a quality of wisdom from above?","explanation":"James describes wisdom from above as first pure, then peaceable, reasonable, ready to obey, and full of mercy and good fruits."},{"id":869,"topic":"christianliving","q":"How should people treat others according to Matthew 7:12?","explanation":"Jesus says to treat others as we would want them to treat us and relates that principle to the Law and the Prophets."}];
