function bu3832CanonId(id){return BU3832_HISTORY_ALIASES[id]||id}
function bu3832ChapterId(q){
 const first=String(q.ref||'').split(/[;,]/)[0].trim();
 const match=first.match(/^(.+?)\s+(\d+)(?::|$)/);
 return match?(match[1].toLowerCase()+'/'+match[2]):first.toLowerCase();
}
function bu3832VerseLinks(ref){
 const parts=String(ref||'').split(/\s*;\s*/).filter(Boolean);
 let lastBook='';
 const chapters=new Map();
 for(const part of parts){
   const m=part.match(/^(.+?)\s+(\d+):/);
   if(m)lastBook=m[1];
   const resolved=m?part:(lastBook+' '+part).trim();
   const url=scriptureUrl(resolved);
   if(!chapters.has(url))chapters.set(url,[]);
   chapters.get(url).push(resolved);
 }
 return [...chapters].map(([url,labels])=>
   `<a class="bu35-scripture" target="_blank" rel="noopener noreferrer" href="${url}">Read ${bu35Escape(labels.join('; '))} on JW.org ↗</a>`
 ).join(' ');
}

const BU3831_HISTORY_KEY='bible-unfolded-family-question-history-v3831';
let bu3831History=(()=>{
 try {
  const stored=JSON.parse(localStorage.getItem(BU3831_HISTORY_KEY)||'null');
  if(stored&&Array.isArray(stored.seen)&&stored.cycles&&typeof stored.cycles==='object')return stored;
 }catch(_){}
 // Carry forward questions the user saw in v3.8.30 rather than resetting them on update.
 const legacy=new Set();
 for(const entry of Object.values(bu3830History||{}))if(Array.isArray(entry?.seen))for(const id of entry.seen)legacy.add(id);
 return {seen:[...legacy],cycles:{},migratedFrom3830:true};
})();
bu3831History.seen=[...new Set(bu3831History.seen.map(bu3832CanonId))];
function bu3831Persist(){try{localStorage.setItem(BU3831_HISTORY_KEY,JSON.stringify(bu3831History))}catch(_){}}
function bu3831Question(g,id){
 const key=id+':'+bu35TurnNumber();
 if(!g.familyTriviaSnapshots)g.familyTriviaSnapshots={};
 if(!g.familyTriviaUsed)g.familyTriviaUsed=[];
 if(g.familyTriviaSnapshots[key])return g.familyTriviaSnapshots[key];
  g.familyTriviaUsed=g.familyTriviaUsed.map(bu3832CanonId);
  bu3831History.seen=[...new Set(bu3831History.seen.map(bu3832CanonId))];
  const pool=bu3830Pool(g),inSession=new Set(g.familyTriviaUsed),seen=new Set(bu3831History.seen);
 const remaining=pool.filter(q=>!inSession.has(bu3830Id(q)));
 let fresh=remaining.filter(q=>!seen.has(bu3830Id(q)));
 let review=false;
 if(!fresh.length&&remaining.length){
  // Only recycle after all not-yet-asked questions in this subject have been tried.
  const identities=new Set(pool.map(bu3830Id));
  bu3831History.seen=bu3831History.seen.filter(key=>!identities.has(key));
  bu3831History.cycles[g.topic]=(bu3831History.cycles[g.topic]||0)+1;
  fresh=remaining;review=true;
 }
 if(!fresh.length){
  // Exception: a single long session exhausted its own topic; show the wider mix label.
  const inTopic=new Set((BU3826_COLLECTIONS[g.topic]?.keys||[g.topic]));
  const wider=BU34_KEYS.filter(k=>!inTopic.has(k)).flatMap(k=>BU34_BANK[k].map(q=>({...q,topic:k,__outside:true})))
    .filter(q=>!inSession.has(bu3830Id(q)));
  fresh=wider.filter(q=>!seen.has(bu3830Id(q)));
  if(!fresh.length)fresh=wider;
 }
 if(!fresh.length)fresh=remaining.length?remaining:pool;
 // Prefer four different source chapters before returning to the same scene.
 // This is a preference, not a hard gate: a one-chapter topic remains playable.
 // Older saved games may have only two stored chapters; both are preserved.
 const recent=(g.familyRecentChapters||[]).slice(-4);
 const varied=fresh.filter(q=>!recent.includes(bu3832ChapterId(q)));
 if(varied.length)fresh=varied;
 const chosen=bu3830WeightedPick(fresh,g.difficulty||'intermediate');
 if(chosen)g.familyRecentChapters=[...recent,bu3832ChapterId(chosen)].slice(-4);
 if(!chosen)return {q:'No further questions available.',choices:['Continue','Continue','Continue','Continue'],correct:0,explanation:'Choose a different topic to keep learning.',ref:'Matthew 28:1'};
 const chosenId=bu3830Id(chosen);
 review=review||seen.has(chosenId)||(bu3831History.cycles[g.topic]||0)>0;
 const result=bu3830BalancedAnswers(g,{...chosen,__review:review});
 g.familyTriviaSnapshots[key]=result;
 g.familyTriviaUsed.push(chosenId);
 if(!bu3831History.seen.includes(chosenId))bu3831History.seen.push(chosenId);
 bu3831Persist();bu35Save();
 return result;
}

