const bu3833ClueCycle={};
function bu3833FreeWordClue(){
 const pack=trailIndex(),rec=trailRecord();
 // Favor the biblical anchor when it is still unsolved; then the remaining words.
 const remain=pack.words.filter(w=>!rec.solved.includes(w.word));
 if(!remain.length)return;
 const sorted=remain.slice().sort((a,b)=>(a.word===pack.bank?-1:0)-(b.word===pack.bank?-1:0));
 const n=bu3833ClueCycle[pack.bank]||0;
 const selected=sorted[n%sorted.length];
 bu3833ClueCycle[pack.bank]=n+1;
 const hint=(BU3833_CLUES[pack.bank]||{})[selected.word]||'An ordinary word formed from this wheel';
 trailSelected=[];
 trailNote=`FREE WORD CLUE · ${selected.word.length} letters: ${hint}. Use the same wheel; you are not charged Insight Tokens.`;
 const target=document.getElementById('trail-feedback');
 if(target)target.textContent=trailNote;
 const preview=document.getElementById('trail-word-preview');if(preview)preview.textContent=`${selected.word.length}-LETTER CLUE`;
}
