/* Guided Word Trails: first-letter guidance and no-prize answer reveal.
   Keep existing trail progress schema, letter hints and regular word rewards. */
/* Chat 5 approved fix: record once-per-word costs in the EXISTING wallet's
   economy.earned list. Do not add a new localStorage key or reset any progress.
   Markers are not rewards and use their own reserved prefix. */
function buChat5ChargeOnce(marker,cost){
  bu3824RefreshWallet(); // Respect changes from another tab before charging.
  if(economy.earned.includes(marker))return {ok:true,charged:false};
  const originalPoints=economy.points,originalEarned=economy.earned.slice();
  economy.earned.push(marker);economy.points-=cost;
  if(!saveEconomy()){
    economy.points=originalPoints;economy.earned=originalEarned;
    updateWallet();return {ok:false,charged:false};
  }
  updateWallet();return {ok:true,charged:true};
}
function bu3834TargetWord(){
 const p=trailIndex(),d=trailRecord();
 const remain=p.words.filter(w=>!d.solved.includes(w.word));
 return remain.find(w=>w.word===p.bank)||remain[0]||null;
}
function bu3834TrailLetterGuide(){
  const p=trailIndex(),t=bu3834TargetWord();if(!t)return;
  const marker='chat5-trail-guide-v1:'+p.bank+':'+t.word;
  const charge=trailIsReplay?{ok:true,charged:false}:buChat5ChargeOnce(marker,10);
  if(!charge.ok){
    trailNote='Your Points could not be saved. The guided letter was not charged or shown.';
    trailSelected=[];crossRender();return;
  }
  const costNote=trailIsReplay?'Replay — no Points deducted.':charge.charged?'−10 Points (once for this word).':'Already paid — no additional Points deducted.';
  trailNote=`GUIDED LETTER · ${t.word.length} letters, begins with ${t.word[0]}. ${BU3833_CLUES[p.bank]?.[t.word]||'Use the wheel to form the word.'} (${costNote})`;
  trailSelected=[];crossRender();
}function bu3834TrailReveal(){
  const p=trailIndex(),d=trailRecord(),t=bu3834TargetWord();if(!t)return;
  const prompt=trailIsReplay
    ?'Show the complete word? Replays have no additional Points penalty or discovery reward.'
    :'Show a complete word and deduct 25 Points? No word-completion points will be awarded.';
  if(!confirm(prompt))return;
  if(d.solved.includes(t.word))return;
  const marker='chat5-trail-reveal-v1:'+p.bank+':'+t.word;
  const charge=trailIsReplay?{ok:true,charged:false}:buChat5ChargeOnce(marker,25);
  if(!charge.ok){
    trailNote='Your Points could not be saved. The word was not revealed.';
    trailSelected=[];crossRender();return;
  }
  // Do NOT invoke trailTry / awardOnce: no discovery prize on a full reveal.
  d.solved.push(t.word);if(!trailIsReplay)trailSave();
  const costNote=trailIsReplay?'Replay: no Points deducted':charge.charged?'−25 Points':'No additional Points deducted';
  trailSelected=[];trailNote=`LEARNED: ${t.word} — ${BU3833_CLUES[p.bank]?.[t.word]||'A word from this letter wheel.'} (${costNote}; no discovery reward.)`;
  crossRender();
}const bu3834PreviousCrossRender=crossRender;
crossRender=function(){
 bu3834PreviousCrossRender();
 const wheel=document.getElementById('xword-wheel');if(!wheel)return;
 const rail=wheel.parentElement?.querySelector('.trail-action-rail');
 if(rail&&!document.getElementById('trail-word-guide')){
  const guide=document.createElement('button');guide.type='button';guide.id='trail-word-guide';guide.className='trail-rail-btn';
  guide.innerHTML='A<small>−10 pt</small>';guide.title='Guided first letter, deduct 10 Points once per word';
  guide.setAttribute('aria-label','Guided first letter, costs 10 Points');guide.onclick=bu3834TrailLetterGuide;
  rail.insertBefore(guide,document.getElementById('trail-hint'));
 }
 if(rail&&!document.getElementById('trail-word-reveal')){
  const reveal=document.createElement('button');reveal.type='button';reveal.id='trail-word-reveal';reveal.className='trail-rail-btn';
  reveal.innerHTML='✓<small>−25 pt</small>';reveal.title='Show word and learn, deduct 25 Points, no discovery reward';
  reveal.setAttribute('aria-label','Reveal a word, deduct 25 Points');reveal.onclick=bu3834TrailReveal;
  rail.appendChild(reveal);
 }
};


